let data = msg.payload;

if (typeof data === "string") {
    try {
        data = JSON.parse(data);
    } catch (e) {
        node.error("Invalid JSON payload: " + e.message, msg);
        return null;
    }
}

// Raw continuous features for the AI/ML model.
const reading = {
    pm25: Number(data.pm25),
    temperature: Number(data.temperature),
    humidity: Number(data.humidity),
    pressure: Number(data.pressure)
};

// ------------------------------------------------------------
// VALIDATION 1: reject missing / non-numeric fields
// ------------------------------------------------------------
for (const [key, val] of Object.entries(reading)) {
    if (!Number.isFinite(val)) {
        node.warn(`Rejected reading: invalid ${key} = ${JSON.stringify(data[key])}`);
        return null;
    }
}

// ------------------------------------------------------------
// VALIDATION 2: reject physically implausible values
// Tune these ranges to match your actual sensor's real specs.
// ------------------------------------------------------------
const ranges = {
    pm25: [0, 1000],
    temperature: [-20, 60],
    humidity: [0, 100],
    pressure: [500, 1100]
};

for (const [key, [min, max]] of Object.entries(ranges)) {
    if (reading[key] < min || reading[key] > max) {
        node.warn(`Rejected reading: ${key}=${reading[key]} out of range [${min}, ${max}]`);
        return null;
    }
}

// ------------------------------------------------------------
// ATTACH PAYLOAD AND HEADERS FOR FLASK
// ------------------------------------------------------------
msg.payload = reading;
msg.headers = {
    "Content-Type": "application/json"
};

return msg;

let history = global.get("aerosense_history") || [];

if (msg.payload && msg.payload.pm25 !== undefined) {
    const timestamp = new Date().toISOString();

    // 1. Memory Storage for UI (Increased limit to 10,000 points for longer history view)
    const newPoint = {
        timestamp: timestamp,
        pm25: msg.payload.pm25,
        temp: msg.payload.temperature,
        hum: msg.payload.humidity,
        pres: msg.payload.pressure
    };
    history.push(newPoint);
    if (history.length > 10000) history.shift(); // Keep up to 10,000 readings in RAM
    global.set("aerosense_history", history);

    // 2. Disk Storage formatting (Permanent CSV archive for model retraining)
    // Write a header once if the archive file is empty/new.
    let headerWritten = global.get("aerosense_csv_header_written");
    let csvOut = "";
    if (!headerWritten) {
        csvOut += "timestamp,pm25,temperature,humidity,pressure\n";
        global.set("aerosense_csv_header_written", true);
    }
    csvOut += `${timestamp},${msg.payload.pm25},${msg.payload.temperature},${msg.payload.humidity},${msg.payload.pressure}\n`;

    return { payload: csvOut };
}
return null;

const result = msg.payload;

// ============================================================
// 0. HTTP STATUS CHECK
// ============================================================
if (msg.statusCode !== undefined && (msg.statusCode < 200 || msg.statusCode >= 300)) {
    node.error("Flask /predict returned HTTP " + msg.statusCode + ": " + JSON.stringify(result), msg);
    return null;
}

if (!result || typeof result !== "object") {
    node.warn("No valid response received from Flask AI/ML API.");
    return null;
}

// ============================================================
// 1. CLASS DEFINITIONS
// ============================================================
const classMap = {
    0: "Very Good",
    1: "Good",
    2: "Moderate",
    3: "Unhealthy"
};

const reverseClassMap = {
    "very good": 0,
    "very_good": 0,
    "very-good": 0,
    "good": 1,
    "moderate": 2,
    "unhealthy": 3
};

const allowedClasses = [
    "Very Good",
    "Good",
    "Moderate",
    "Unhealthy"
];

// ============================================================
// 2. GET PREDICTION FROM FLASK API (DAY 1)
// ============================================================
let category = null;
if (result.forecast && result.forecast.day1) {
    category = result.forecast.day1.predicted_category;
} else {
    category = result.predicted_category_tomorrow || result.prediction || result.aqi_category || result.category || null;
}

// ============================================================
// 3. GET CLASS ID
// ============================================================
let classId = null;
if (result.class_id !== undefined && result.class_id !== null && result.class_id !== "") {
    classId = Number(result.class_id);
}

// ============================================================
// 4. HANDLE NUMERIC PREDICTION
// ============================================================
if (
    typeof category === "number" ||
    (typeof category === "string" && /^[0-3]$/.test(category.trim()))
) {
    const numericClass = Number(category);
    if (numericClass >= 0 && numericClass <= 3) {
        classId = numericClass;
        category = classMap[numericClass];
    }
}

// ============================================================
// 5. NORMALIZE MODEL TEXT
// ============================================================
if (category !== null && category !== undefined) {
    const normalized = String(category)
        .trim()
        .replace(/\s+/g, " ")
        .replace(/[.!]+$/, "")
        .toLowerCase();

    const aliases = {
        "very good": "Very Good",
        "very_good": "Very Good",
        "very-good": "Very Good",
        "class 0": "Very Good",
        "good": "Good",
        "class 1": "Good",
        "moderate": "Moderate",
        "moderate or worse": "Moderate",
        "moderate_or_worse": "Moderate",
        "class 2": "Moderate",
        "unhealthy": "Unhealthy",
        "unhealthy or worse": "Unhealthy",
        "unhealthy_or_worse": "Unhealthy",
        "unhealthy/worse": "Unhealthy",
        "unhealthy or above": "Unhealthy",
        "class 3": "Unhealthy"
    };

    if (aliases[normalized]) {
        category = aliases[normalized];
    } else {
        node.warn("Unrecognized category text -> raw: " + JSON.stringify(category) + ", normalized: " + JSON.stringify(normalized));
        category = String(category).trim();
    }
}

// ============================================================
// 6. DERIVE CLASS ID FROM CATEGORY
// ============================================================
if (classId === null && category && reverseClassMap[category.toLowerCase()] !== undefined) {
    classId = reverseClassMap[category.toLowerCase()];
}

// ============================================================
// 7. VALIDATE AI/ML OUTPUT
// ============================================================
if (!allowedClasses.includes(category)) {
    node.warn("Unsupported AI/ML prediction received: " + JSON.stringify(category));
    return null;
}

// ============================================================
// 8. VALIDATE / CORRECT CLASS ID
// ============================================================
if (classId === null || !Number.isInteger(classId) || classId < 0 || classId > 3) {
    classId = reverseClassMap[category.toLowerCase()];
}

if (classId !== null && classMap[classId] !== category) {
    node.warn("Class mismatch detected. Category=" + category + ", class_id=" + classId);
    classId = reverseClassMap[category.toLowerCase()];
}

// ============================================================
// 9. CONFIDENCE
// ============================================================
let confidence = null;
let resultConf = (result.forecast && result.forecast.day1) ? result.forecast.day1.confidence : result.confidence;

if (resultConf !== undefined && resultConf !== null) {
    confidence = Number(resultConf);
    if (Number.isFinite(confidence)) {
        if (confidence > 1) {
            confidence = confidence / 100;
        }
        confidence = Math.max(0, Math.min(1, confidence));
    } else {
        confidence = null;
    }
}

// ============================================================
// 10. CLASS PROBABILITIES
// ============================================================
const probabilities =
    (result.forecast && result.forecast.day1 && result.forecast.day1.class_probabilities) ||
    result.class_probabilities ||
    result.probabilities ||
    {};

// ============================================================
// 11. GET INPUT FEATURES
// ============================================================
const rawInputs = result.input_received || result.inputs || {};

const inputs = {
    pm25: Number.isFinite(Number(rawInputs.pm25)) ? Number(rawInputs.pm25) : null,
    temperature: Number.isFinite(Number(rawInputs.temperature)) ? Number(rawInputs.temperature) : null,
    humidity: Number.isFinite(Number(rawInputs.humidity)) ? Number(rawInputs.humidity) : null,
    pressure: Number.isFinite(Number(rawInputs.pressure)) ? Number(rawInputs.pressure) : null
};

// ============================================================
// 12. FRIENDLY MESSAGE
// ============================================================
const friendlyMessages = {
    "Very Good": "🌿 Great news! Air quality is expected to be very good over the next 24 hours. It should be a comfortable time for outdoor activities.",
    "Good": "🌿 Good news! Air quality is expected to stay good over the next 24 hours. Outdoor activities should be comfortable for most people.",
    "Moderate": "⚠️ Air quality is expected to be moderate over the next 24 hours. Most people can continue normal activities, but sensitive individuals may want to take a little extra care.",
    "Unhealthy": "🚨 Please take care! Air quality is expected to be unhealthy over the next 24 hours. Consider reducing prolonged outdoor exposure."
};

const friendlyMessage = friendlyMessages[category];

// ============================================================
// 13. HUMAN-READABLE CLASS NUMBER
// ============================================================
const classNumber = classId + 1;
const classDisplay = `Class ${classNumber}/4`;

// ============================================================
// 14. SAVE LATEST RESULT FOR DASHBOARD (INCLUDES 3-DAY FORECAST)
// ============================================================
global.set("aerosense_latest", {
    timestamp: new Date().toISOString(),
    forecast_horizon: "Next 24 hours",
    forecast_horizon_code: "T+24h",
    model_type: "Random Forest Classifier",
    predicted_category: category,
    class_id: classId,
    class_number: classNumber,
    confidence: confidence,
    probabilities: probabilities,
    inputs: inputs,
    friendly_message: friendlyMessage,
    full_forecast: result.forecast || null,
    status: "ok"
});

// ============================================================
// 15. TELEGRAM ALERT CONDITIONS (UPDATED FOR 3-DAY)
// ============================================================
const alertCategories = ["Moderate", "Unhealthy"];

// Extract the categories for all 3 days
let d1Cat = result.forecast && result.forecast.day1 ? result.forecast.day1.predicted_category : category;
let d2Cat = result.forecast && result.forecast.day2 ? result.forecast.day2.predicted_category : "N/A";
let d3Cat = result.forecast && result.forecast.day3 ? result.forecast.day3.predicted_category : "N/A";

// Check if ANY of the next 3 days have an elevated risk
const needsAlert = alertCategories.includes(d1Cat) || 
                   alertCategories.includes(d2Cat) || 
                   alertCategories.includes(d3Cat);

if (!needsAlert) {
    // Stop flow if all 3 days are Good/Very Good
    return null; 
}

// ============================================================
// 16. TELEGRAM BOT TOKEN
// ============================================================
const token = "8981886657:AAGdAUEOZ7YLSavBUNEMQZmq6g3L2oGe37M";

if (!token) {
    node.error("Token is missing.");
    return null;
}

// ============================================================
// 17. GET TELEGRAM SUBSCRIBERS
// ============================================================
let subscribers = global.get("telegram_subscribers") || [];
if (subscribers.length === 0) {
    subscribers = ["8684688972"];
}

// ============================================================
// 18. FORMAT SENSOR VALUES
// ============================================================
const pm25Text = inputs.pm25 !== null ? inputs.pm25 + " µg/m³" : "N/A";
const tempText = inputs.temperature !== null ? inputs.temperature + " °C" : "N/A";
const humidityText = inputs.humidity !== null ? inputs.humidity + " %" : "N/A";
const pressureText = inputs.pressure !== null ? inputs.pressure + " hPa" : "N/A";

// ============================================================
// 19. BUILD TELEGRAM MESSAGE
// ============================================================
const getEmoji = (c) => {
    if (c === "Very Good" || c === "Good") return "🟢";
    if (c === "Moderate") return "🟡";
    if (c === "Unhealthy") return "🔴";
    return "⚪";
};

let forecast3DaySummary = "";
if (result.forecast) {
    forecast3DaySummary = 
        `\n\n📅 *3-Day Forecast Overview*\n` +
        `• Day 1 (24h): ${getEmoji(d1Cat)} *${d1Cat}*\n` +
        `• Day 2 (48h): ${getEmoji(d2Cat)} *${d2Cat}*\n` +
        `• Day 3 (72h): ${getEmoji(d3Cat)} *${d3Cat}*`;
}

const telegramText =
    "🚨 *AeroSense Air Quality Alert*\n\n" +
    friendlyMessage +
    forecast3DaySummary + "\n\n" +
    "━━━━━━━━━━━━━━━━━━\n\n" +
    "🤖 *AI/ML Forecast Details*\n" +
    "• Current Input Class: *" + classDisplay + "*\n" +
    "• Model: *Random Forest Classifier*\n\n" +
    "📊 *Latest Edge Sensors*\n" +
    "• PM2.5: " + pm25Text + "\n" +
    "• Temperature: " + tempText + "\n" +
    "• Humidity: " + humidityText + "\n" +
    "• Pressure: " + pressureText + "\n\n" +
    "━━━━━━━━━━━━━━━━━━\n\n" +
    "🌿 Stay aware and take care outside.";

// ============================================================
// 20. PREPARE REQUESTS FOR ALL SUBSCRIBERS
// ============================================================
const outputMessages = [];

for (let i = 0; i < subscribers.length; i++) {
    let telegramMsg = {};
    telegramMsg.url = "https://api.telegram.org/bot" + token + "/sendMessage";
    telegramMsg.headers = { "Content-Type": "application/json" };
    telegramMsg.payload = {
        chat_id: subscribers[i],
        text: telegramText,
        parse_mode: "Markdown"
    };
    outputMessages.push(telegramMsg);
}

// ============================================================
// 21. SEND TO TELEGRAM HTTP REQUEST NODE
// ============================================================
return [outputMessages];

let subscribers = global.get("telegram_subscribers") || [];
const chatId = msg.payload.chatId;
const type = msg.payload.type;

// Only process text messages
if (type !== "message") return null;

const command = msg.payload.content;

if (command === "/start") {
    // Add user to subscribers if not already in the list
    if (!subscribers.includes(chatId)) {
        subscribers.push(chatId);
        global.set("telegram_subscribers", subscribers);
    }

    msg.payload.type = "message";
    msg.payload.content = "🌿 *Welcome to AeroSense AI!*\n\nYou are now subscribed to 24-hour air quality forecast alerts. I will notify you automatically if the air quality becomes Moderate or Unhealthy.\n\nYou can also type /status at any time to check the current forecast.";
    msg.payload.options = { parse_mode: "Markdown" };
    return msg;
}

if (command === "/status") {
    const latest = global.get("aerosense_latest");
    msg.payload.type = "message";

    if (latest && latest.predicted_category) {
        msg.payload.content = `🌤️ *Current Status*\nPredicted Class: *${latest.predicted_category}*\n\n📊 *Latest Sensors*\nPM2.5: ${latest.inputs.pm25} µg/m³\nTemp: ${latest.inputs.temperature} °C\nHum: ${latest.inputs.humidity} %\nPres: ${latest.inputs.pressure} hPa`;
    } else {
        msg.payload.content = "⏳ No sensor data received yet. Please wait for the next edge reading.";
    }
    msg.payload.options = { parse_mode: "Markdown" };
    return msg;
}

return null;
